  add('2021-2026','policy',[
    ['Đại hội XIV – mô hình tăng trưởng mới','Kiên định chủ nghĩa Mác – Lênin, tư tưởng Hồ Chí Minh, mục tiêu độc lập dân tộc và chủ nghĩa xã hội; khoa học – công nghệ, đổi mới sáng tạo, chuyển đổi số là động lực chính; phát triển kinh tế tư nhân là một động lực quan trọng nhất; hoàn thiện thể chế, chuyển đổi xanh, năng lượng và chất lượng nguồn nhân lực là các cấu phần của mô hình tăng trưởng mới. Chỉ tiêu: GDP bình quân 2026–2030 từ 10%/năm trở lên; GDP bình quân đầu người khoảng 8.500 USD năm 2030; kinh tế số khoảng 30% GDP. Nhấn mạnh quan hệ giữa phát triển và ổn định; kinh tế – xã hội – môi trường với quốc phòng, an ninh, đối ngoại; xây dựng Đảng với năng lực quản trị quốc gia.'],
    ['Đối ngoại và hội nhập trong bối cảnh mới','Độc lập, tự chủ, đa phương hóa, đa dạng hóa, bảo đảm cao nhất lợi ích quốc gia – dân tộc trên cơ sở luật pháp quốc tế; mở rộng và nâng cấp nhiều khuôn khổ quan hệ đối tác, tích cực tham gia cơ chế đa phương, xử lý môi trường cạnh tranh nước lớn ngày càng phức tạp. Hội nhập không chỉ theo chiều kinh tế mà trở thành hội nhập sâu rộng, toàn diện (Nghị quyết 59-NQ/TW năm 2025 hệ thống hóa yêu cầu này).'],
    ['Năm mệnh đề có thể dùng làm kết luận tự luận','(1) Độc lập dân tộc là điều kiện tiên quyết để nhân dân làm chủ và phát triển đất nước; mục tiêu độc lập được gắn với định hướng xã hội chủ nghĩa. (2) Đường lối chỉ đúng khi xuất phát từ thực tiễn, xác định đúng mâu thuẫn chủ yếu và có khả năng tập hợp lực lượng rộng rãi. (3) Sự lãnh đạo của Đảng được kiểm nghiệm không chỉ ở việc đề ra chủ trương mà còn ở năng lực tổ chức, tự điều chỉnh và sửa chữa sai lầm. (4) Sức mạnh dân tộc được phát huy cao nhất khi kết hợp nội lực với sức mạnh thời đại, độc lập tự chủ với hội nhập quốc tế. (5) Đổi mới là quá trình liên tục; từ đổi mới tư duy kinh tế đến đổi mới thể chế và hiện nay là đổi mới mô hình tăng trưởng dựa trên khoa học – công nghệ và năng suất.']
  ]);
  add('2021-2026','lessons',[
    'Khi ôn tập, không chỉ trả lời “sự kiện gì xảy ra”, mà phải trả lời được “vì sao xuất hiện – Đảng lựa chọn gì – lựa chọn đó giải quyết vấn đề nào – kết quả và bài học là gì”; giá trị lớn nhất của môn học nằm ở khả năng giải thích mối quan hệ giữa bối cảnh – đường lối – tổ chức thực hiện – kết quả – bài học.'
  ]);
